svg.script:
// 
(function () {
  var svg    = document.querySelector('svg');
  var prefix = document.getElementById('brand-prefix');
  var dots   = document.getElementById('circuit-dots');
  var suffix = document.getElementById('product-suffix');
  var brR    = document.getElementById('bracket-right');

  if (!svg || !prefix || !suffix) return;

  // ── ?mode= / #hash mode switch with inline fallback ──
  var MODES = {
    'dark': {'--logotype-primary':'#E2E8F0','--logotype-secondary':'#F8FAFC','--logotype-accent':'#CBD5E1','--logotype-glow':'#E2E8F0','--logotype-shadow':'rgba(0,0,0,0.7)'},
    'cb-deutan': {'--logotype-primary':'#648FFF','--logotype-secondary':'#FFB000','--logotype-accent':'#785EF0','--logotype-glow':'#648FFF'},
    'cb-protan': {'--logotype-primary':'#648FFF','--logotype-secondary':'#DC267F','--logotype-accent':'#FFB000','--logotype-glow':'#648FFF'},
    'cb-tritan': {'--logotype-primary':'#D55E00','--logotype-secondary':'#CC79A7','--logotype-accent':'#D55E00','--logotype-glow':'#CC79A7'},
    'cb-deutan-dark': {'--logotype-primary':'#85AAFF','--logotype-secondary':'#FFC940','--logotype-accent':'#9B85FF','--logotype-glow':'#85AAFF','--logotype-shadow':'rgba(0,0,0,0.7)'},
    'cb-protan-dark': {'--logotype-primary':'#85AAFF','--logotype-secondary':'#FF5CA1','--logotype-accent':'#FFC940','--logotype-glow':'#85AAFF','--logotype-shadow':'rgba(0,0,0,0.7)'},
    'cb-tritan-dark': {'--logotype-primary':'#FF8533','--logotype-secondary':'#E09DBF','--logotype-accent':'#FF8533','--logotype-glow':'#E09DBF','--logotype-shadow':'rgba(0,0,0,0.7)'}
  };
  try {
    var search = window.location.search || '';
    var hash = window.location.hash || '';
    var params = new URLSearchParams(search);
    var mode = params.get('mode') || hash.replace('#', '') || null;
    if (mode && mode !== 'light') {
      if (mode.indexOf('-dark') > 0 && mode.indexOf('cb-') === 0) {
        svg.classList.add('dark');
        svg.classList.add(mode.replace('-dark', ''));
      } else {
        svg.classList.add(mode);
      }
      var props = MODES[mode];
      if (props) { for (var k in props) svg.style.setProperty(k, props[k]); }
    }
  } catch (e) {}

  // Wait for fonts to load before measuring
  var measure = function () {
    var GAP     = 3;   // px between prefix and dots (tight, like a colon)
    var DOT_GAP = 3;   // px between dots and suffix (tight, like a colon)
    var PAD_R   = 14;  // right padding after suffix before bracket
    var MARGIN  = 8;   // margin after bracket to edge

    // Measure brand prefix bounding box
    var pBox  = prefix.getBBox();
    var pEnd  = pBox.x + pBox.width;

    // Position circuit dots horizontally after the prefix
    var dotX = pEnd + GAP;
    var dotCircles = dots.querySelectorAll('circle');
    for (var i = 0; i < dotCircles.length; i++) {
      dotCircles[i].setAttribute('cx', dotX);
    }

    // Position product suffix after the dots
    var suffixX = dotX + DOT_GAP;
    suffix.setAttribute('x', suffixX);

    // Measure suffix bounding box (after repositioning)
    var sBox = suffix.getBBox();
    var sEnd = sBox.x + sBox.width;

    // Position right bracket
    var brX = sEnd + PAD_R;
    if (brR) {
      brR.setAttribute('points',
        (brX - 6) + ',18 ' + brX + ',18 ' + brX + ',108 ' + (brX - 6) + ',108'
      );
    }

    // Resize the viewBox to fit
    var totalW = brX + MARGIN;
    svg.setAttribute('viewBox', '0 0 ' + totalW + ' 130');
  };

  // Try to use Font Face API; fall back to a timeout for older browsers
  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(measure);
  } else {
    setTimeout(measure, 200);
  }
})();
//
